/* Project-specific plans and architectural references. Local files are not uploaded to a server. */
window.SHCustomerPlanSet=(()=>{
const pages=['Plan set'],categories=['Floor plan','Elevations','Render'],views=['Front exterior','Rear exterior','Interior','Other'],statuses=['Concept','Contract reference','Issued for review','Superseded'];
const imageTypes=['image/jpeg','image/png','image/webp'],fileTypes=[...imageTypes,'application/pdf'];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();let urls=[];
function init(c){for(const key of ['planSetDocuments','planSetSettings','documents'])if(!Array.isArray(c.store[key]))c.store[key]=[];}
function setting(c){return c.store.planSetSettings.find(x=>x.projectId===c.projectId)||{projectId:c.projectId,standardRenderCount:3,selectedRenderIds:[],heroDocumentId:''};}
function source(c,d){return d.sourceDocumentId?c.store.documents.find(x=>x.id===d.sourceDocumentId&&x.projectId===c.projectId&&Array.isArray(x.visibility)&&x.visibility.includes('customer')):null;}
function rows(c){return c.store.planSetDocuments.filter(d=>d.projectId===c.projectId&&Array.isArray(d.visibility)&&d.visibility.includes('customer')&&(!d.sourceDocumentId||source(c,d)));}
function https(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}}
const options=(values,value)=>values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const field=(name,label,value='',extra='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
function availableImage(c,d){return d&&!d.sourceDocumentId&&imageTypes.includes(d.attachment?.type)&&d.status!=='Superseded';}
function label(d){return d.status==='Contract reference'?'Contract reference · identified by Shed House':d.status;}
function metadata(c,d){const original=source(c,d);return `<p class="ps-meta">Version ${esc(d.version)} · ${esc(label(d))}<br>${esc(d.provenance)}${original?`<br>Source register: ${esc(original.name)} · Version ${esc(original.version||'Unspecified')} · ${esc(original.status||'Unreviewed')}`:''}</p>`;}
function access(c,d){if(d.sourceDocumentId){const original=source(c,d),url=https(original?.url);return url?`<a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open registered ${esc(d.category.toLowerCase())} ↗</a><p class="small">External service permissions apply. Download through its document viewer.</p>`:'<p class="small">Source document has no valid HTTPS link. Ask Shed House to update the register.</p>';}return d.attachment?`<div data-ps-file="${esc(d.id)}" class="ps-file"><span class="small">Checking local file…</span></div>`:'<p class="small">File awaiting Shed House.</p>';}
function panel(c){init(c);const s=setting(c),docs=rows(c),hero=docs.find(d=>d.id===s.heroDocumentId&&d.category==='Render'&&availableImage(c,d));return `<section class="ps-dashboard card"><div class="ps-hero">${hero?`<div class="ps-hero-picture" data-ps-image="${esc(hero.id)}"><p class="small">Loading your project image from this device…</p></div>`:'<div class="ps-hero-picture ps-test-picture"><img src="assets/customer-test-house.png" alt="Customer test image: timber-clad gabled house in a meadow" loading="eager"><span class="ps-test-label">TEST IMAGE · Awaiting project renders</span></div>'}<div class="ps-hero-copy"><span class="eyebrow">${hero?'YOUR PROJECT REFERENCE':'YOUR PROJECT VISION · TEST IMAGE'}</span><h2>${esc(c.project?.name||'Your Shed House')}</h2>${hero?`<p>${esc(hero.caption||hero.name)}</p>${metadata(c,hero)}`:'<p>This temporary customer test image is shown until your project renders are available. It does not represent your contracted design.</p>'}<p class="small">Images communicate design intent. Check drawings, specifications and agreed contract documents for the scope.</p><button class="primary" data-go="Plan set" data-ps-go>View your plan set →</button></div></div><div class="ps-quick" aria-label="Quick access to project plans">${['Floor plan','Elevations'].map(cat=>{const d=docs.filter(d=>d.category===cat&&d.status!=='Superseded').slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];return `<div><h3>${cat}</h3>${d?`${metadata(c,d)}${access(c,d)}`:'<p class="small">Awaiting project document from Shed House.</p>'}</div>`;}).join('')}<div><h3>Your selected renders</h3><p>${docs.filter(d=>d.category==='Render'&&d.status!=='Superseded'&&(s.selectedRenderIds||[]).includes(d.id)).length} selected · Standard set ${esc(s.standardRenderCount||3)}</p><p class="small">Suggested views: front exterior, rear exterior and interior.</p><button class="secondary" data-ps-go>Open render collection</button></div></div></section>`;}
function render(page,c){init(c);if(!pages.includes(page))return '';const docs=rows(c),s=setting(c),staff=c.role==='staff';return `<div class="customer-plan-set"><div class="heading"><div><div class="eyebrow">PROJECT PLANS & VISION</div><h1>Your Shed House, in view.</h1><p>${esc(c.project?.name||c.projectId)} · Project-specific plan set</p></div></div>${panel(c)}<div class="ps-notice"><strong>Know which version you are viewing</strong><p>Concept images and contract references are labelled separately. Uploading or selecting a file does not grant consent approval. These files and selections save only in this browser; local files are unavailable on another device.</p></div>${categories.map(category=>`<section class="card"><h2>${category==='Render'?'Selected render collection':category}</h2>${category==='Render'?`<p>Standard package: ${esc(s.standardRenderCount||3)} views. Recommended starting set: front exterior, rear exterior and interior. Shed House can change the count and select the relevant views.</p>`:''}<div class="ps-document-grid">${docs.filter(d=>d.category===category&&(staff||d.status!=='Superseded')).map(d=>`<article class="ps-document"><div class="ps-document-heading"><h3>${esc(d.name)}</h3><span class="tag ${d.status==='Concept'?'amber':'grey'}">${esc(label(d))}</span></div>${category==='Render'?`<p>${esc(d.renderView||'Other')} · ${(s.selectedRenderIds||[]).includes(d.id)?'Included in selected set':'Additional reference'}</p>${availableImage(c,d)?`<div class="ps-thumbnail" data-ps-image="${esc(d.id)}"><p class="small">Loading project image…</p></div>`:''}`:''}<p>${esc(d.caption)}</p>${metadata(c,d)}${access(c,d)}${staff?`<details><summary>Edit document details</summary>${editForm(d)}</details>`:''}</article>`).join('')||`<p>No ${category.toLowerCase()} supplied for this project yet.</p>`}</div></section>`).join('')}${staff?staffForms(c):''}</div>`;}
function editForm(d){return `<form class="ps-form" data-ps-edit="${esc(d.id)}">${field('name','Document name',d.name,'required maxlength="180"')}${field('version','Version / drawing revision',d.version,'required maxlength="100"')}<label>Purpose / status<select name="status">${options(statuses,d.status)}</select></label>${field('provenance','Source / author / issue reference',d.provenance,'required maxlength="250"')}${field('caption','Caption',d.caption,'maxlength="300"')}${field('alt','Image description for screen readers',d.alt,'maxlength="300"')}<p class="small">Contract reference must be explicitly identified from the agreed project documents by Shed House. This is not a consent approval.</p><p class="ps-error" role="alert"></p><button class="secondary">Save document details</button></form>`;}
function staffForms(c){const docs=rows(c),s=setting(c);const sourceDocs=c.store.documents.filter(d=>d.projectId===c.projectId&&d.visibility?.includes('customer')&&https(d.url)&&!c.store.bomDocuments?.some(b=>b.id===d.id));return `<section class="card"><h2>Shed House · Add project plans and renders</h2><p>Upload the actual project file or link a customer-visible document already registered by SH. Do not upload private BOM source files here. Each saved item retains a version and source reference.</p><form class="ps-form" id="ps-upload"><label>Category<select name="category">${options(categories,'Floor plan')}</select></label><label>Render view (renders only)<select name="renderView">${options(views,'Front exterior')}</select></label>${field('name','Document name','','required maxlength="180"')}${field('version','Version / drawing revision','','required maxlength="100"')}<label>Purpose / status<select name="status">${options(statuses,'Concept')}</select></label>${field('provenance','Source / author / issue reference','','required maxlength="250"')}${field('caption','Caption','','maxlength="300"')}${field('alt','Image description for screen readers','','maxlength="300"')}<label>Actual PDF or image file · max 10 MB<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label>Or link an existing customer-visible project document<select name="sourceDocumentId"><option value="">No existing document selected</option>${sourceDocs.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.version)} · ${esc(d.status)}</option>`).join('')}</select></label><label class="ps-check"><input name="acknowledged" type="checkbox" required> I have checked this file belongs to this project and may be shared with its customer. Upload does not grant approval.</label><p class="small">Use one source only. New file metadata enters the shared browser record; file contents stay in device-local storage. No server upload occurs.</p><p class="ps-error" role="alert"></p><button class="primary">Add project document</button></form></section><section class="card"><h2>Shed House · Select the customer’s views</h2><form class="ps-form" id="ps-settings">${field('standardRenderCount','Standard number of renders',s.standardRenderCount||3,'type="number" min="1" max="20" required')}<label>Hero image from this project<select name="heroDocumentId"><option value="">No hero selected</option>${docs.filter(d=>d.category==='Render'&&availableImage(c,d)).map(d=>`<option value="${esc(d.id)}" ${s.heroDocumentId===d.id?'selected':''}>${esc(d.name)} · ${esc(d.version)} · ${esc(d.status)}</option>`).join('')}</select></label><fieldset class="ps-wide"><legend>Include renders in standard customer set</legend>${docs.filter(d=>d.category==='Render'&&d.status!=='Superseded').map(d=>`<label class="ps-check"><input type="checkbox" name="selectedRenderIds" value="${esc(d.id)}" ${(s.selectedRenderIds||[]).includes(d.id)?'checked':''}> ${esc(d.renderView||'Other')} · ${esc(d.name)} · ${esc(d.version)}</label>`).join('')||'<p>No project renders available yet.</p>'}</fieldset><p class="small">Three views are recommended; the selection is configurable rather than limited to three. Only an actual uploaded image can be the hero; external links are never loaded as images.</p><p class="ps-error" role="alert"></p><button class="primary">Save customer plan set</button></form></section>`;}
async function fileRecord(c,d){if(!d?.attachment)return null;const r=await c.files?.get(d.attachment.id);return r&&r.projectId===c.projectId&&r.ownerId===d.id&&r.blob&&fileTypes.includes(r.type)?r:null;}
function bindPanel(c){init(c);for(const url of urls)URL.revokeObjectURL(url);urls=[];document.querySelectorAll('[data-ps-go]').forEach(b=>b.onclick=()=>c.navigate('Plan set'));
document.querySelectorAll('[data-ps-image]').forEach(async element=>{const d=rows(c).find(x=>x.id===element.dataset.psImage&&availableImage(c,x));try{const r=await fileRecord(c,d);if(!element.isConnected)return;element.textContent='';if(!r||!imageTypes.includes(r.type)){element.textContent='Project image is unavailable on this device. Ask Shed House for the actual file.';return;}const url=URL.createObjectURL(r.blob);urls.push(url);const img=document.createElement('img');img.src=url;img.alt=d.alt||`${d.renderView||'Project'} rendering of ${c.project?.name||'your Shed House'}, version ${d.version}`;img.onerror=()=>{element.textContent='This project image cannot be displayed. Open the actual file below or ask Shed House to replace it.';};element.append(img);}catch{element.textContent='Local project image could not be read.';}});
document.querySelectorAll('[data-ps-file]').forEach(async element=>{const d=rows(c).find(x=>x.id===element.dataset.psFile);try{const r=await fileRecord(c,d);if(!element.isConnected)return;element.textContent='';if(!r){element.textContent='Actual file unavailable on this device. Ask Shed House to supply the project file.';return;}const url=URL.createObjectURL(r.blob);urls.push(url);const open=document.createElement('a');open.href=url;open.target='_blank';open.rel='noopener noreferrer';open.className='secondary';open.textContent=`Open ${d.category.toLowerCase()}`;const download=document.createElement('a');download.href=url;download.download=r.name;download.className='secondary';download.textContent='Download file';element.append(open,download);}catch{element.textContent='Local file could not be read.';}});
}
function validateDocument(c,data,file){
 if(!categories.includes(data.category)||!statuses.includes(data.status)||!String(data.name||'').trim()||!String(data.version||'').trim()||!String(data.provenance||'').trim())throw Error('Supply name, version, purpose and provenance.');
 if((!!file)===(!!data.sourceDocumentId))throw Error('Choose exactly one actual file or existing project document.');
 if(file&&(!fileTypes.includes(file.type)||file.size<1||file.size>10*1024*1024))throw Error('Use a non-empty PDF, JPEG, PNG or WebP file up to 10 MB.');
 if(data.sourceDocumentId){const d={sourceDocumentId:data.sourceDocumentId};if(!source(c,d)||!https(source(c,d).url))throw Error('Choose a customer-visible HTTPS document for this project.');}
 return true;
}
function validateSettings(c,data){const docs=rows(c),count=Number(data.standardRenderCount);if(!Number.isInteger(count)||count<1||count>20)throw Error('Choose a standard count from 1 to 20.');if(data.heroDocumentId&&!docs.some(d=>d.id===data.heroDocumentId&&d.category==='Render'&&availableImage(c,d)))throw Error('Choose an actual image from this project.');if((data.selectedRenderIds||[]).some(id=>!docs.some(d=>d.id===id&&d.category==='Render'&&d.status!=='Superseded')))throw Error('Select current renders for this project only.');return true;}
function bind(page,c){bindPanel(c);if(c.role!=='staff')return;const notify=message=>c.notify({title:'Project plan set updated',message,roles:['staff','customer'],projectId:c.projectId,kind:'plan-set'});
const upload=document.getElementById('ps-upload');if(upload)upload.onsubmit=async e=>{e.preventDefault();const error=upload.querySelector('.ps-error'),button=upload.querySelector('button');if(button.disabled)return;error.textContent='';button.disabled=true;let storedId=null;try{const f=new FormData(upload),data=Object.fromEntries(f),file=upload.elements.file.files[0];if(!categories.includes(data.category)||!statuses.includes(data.status)||!data.name.trim()||!data.version.trim()||!data.provenance.trim()||!f.has('acknowledged'))throw Error('Supply the project document details and sharing confirmation.');validateDocument(c,data,file);const id=uid();const record={id,projectId:c.projectId,category:data.category,renderView:data.renderView,name:data.name.trim(),version:data.version.trim(),status:data.status,provenance:data.provenance.trim(),caption:data.caption,alt:data.alt,createdAt:new Date().toISOString(),sourceDocumentId:data.sourceDocumentId||null,visibility:['staff','customer']};if(file){if(!fileTypes.includes(file.type)||file.size<1||file.size>10*1024*1024)throw Error('Use a non-empty PDF, JPEG, PNG or WebP file up to 10 MB.');if(!c.files)throw Error('Device-local file storage is unavailable.');const attachment={id:uid(),name:file.name,type:file.type,size:file.size};await c.files.put({...attachment,projectId:c.projectId,ownerId:id,kind:'plan-set',blob:file,createdAt:record.createdAt});storedId=attachment.id;record.attachment=attachment;}else if(!source(c,record)||!https(source(c,record).url))throw Error('Choose a customer-visible HTTPS document for this project.');c.store.planSetDocuments.push(record);if(c.save()===false){c.store.planSetDocuments.pop();throw Error('Plan metadata could not be saved.');}storedId=null;notify(`${record.name} · Version ${record.version} · ${record.status}. Check the document purpose before use.`);c.navigate('Plan set');}catch(e){if(storedId)await c.files?.remove(storedId).catch(()=>{});error.textContent=e.message||'Could not save project document.';button.disabled=false;}};
document.querySelectorAll('[data-ps-edit]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const d=c.store.planSetDocuments.find(x=>x.id===form.dataset.psEdit&&x.projectId===c.projectId),f=Object.fromEntries(new FormData(form));if(!d)return;if(!statuses.includes(f.status)||!f.name.trim()||!f.version.trim()||!f.provenance.trim()){form.querySelector('.ps-error').textContent='Name, version, purpose and source are required.';return;}const previous={...d};Object.assign(d,{name:f.name.trim(),version:f.version.trim(),status:f.status,provenance:f.provenance.trim(),caption:f.caption,alt:f.alt,updatedAt:new Date().toISOString()});if(c.save()===false){Object.keys(d).forEach(k=>delete d[k]);Object.assign(d,previous);form.querySelector('.ps-error').textContent='Document changes could not be saved.';return;}notify(`${d.name} metadata updated · Version ${d.version} · ${d.status}.`);c.navigate('Plan set');});
const settings=document.getElementById('ps-settings');if(settings)settings.onsubmit=e=>{e.preventDefault();const f=new FormData(settings),count=Number(f.get('standardRenderCount')),hero=f.get('heroDocumentId'),selected=f.getAll('selectedRenderIds'),docs=rows(c);const error=settings.querySelector('.ps-error');try{validateSettings(c,{standardRenderCount:count,heroDocumentId:hero,selectedRenderIds:selected});}catch(e){error.textContent=e.message;return;}if(!Number.isInteger(count)||count<1||count>20){error.textContent='Choose a standard count from 1 to 20.';return;}if(hero&&!docs.some(d=>d.id===hero&&d.category==='Render'&&availableImage(c,d))){error.textContent='Choose an actual image from this project.';return;}if(selected.some(id=>!docs.some(d=>d.id===id&&d.category==='Render'&&d.status!=='Superseded'))){error.textContent='Select current renders for this project only.';return;}let s=c.store.planSetSettings.find(x=>x.projectId===c.projectId);const previous=s?{...s}:null;if(!s){s={projectId:c.projectId};c.store.planSetSettings.push(s);}Object.assign(s,{heroDocumentId:hero,selectedRenderIds:selected,standardRenderCount:count,updatedAt:new Date().toISOString()});if(c.save()===false){if(previous){Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,previous);}else c.store.planSetSettings.splice(c.store.planSetSettings.indexOf(s),1);error.textContent='Plan set selections could not be saved.';return;}notify('Customer hero image and selected project render set updated.');c.navigate('Plan set');};
}
return {pages,render,bind,panel,bindPanel,validateDocument,validateSettings,fileRecord};
})();
